function splitLines(text){ return String(text||'').split(/\n+/).map(function(s){return s.trim();}).filter(function(s){return s.length;}); }
function parseStory(line){
  var parts=line.split(/\s*[\/|，,]\s*/);
  var role=parts[0]||'', goal=parts[1]||'', value=parts[2]||'';
  return {role:role, goal:goal, value:value, raw:line};
}
function genStory(line){
  var s=parseStory(line);
  var role=s.role||'用户', goal=s.goal||s.raw, value=s.value||'达成业务目标';
  var story='作为'+role+'，我希望'+goal+'，以便'+value+'。';
  var ac=['验收标准（Given/When/Then）：',
    'Given 用户已进入相关场景',
    'When 用户'+goal,
    'Then 系统应给出正确结果并满足预期'];
  return {role:role, goal:goal, value:value, story:story, acceptance:ac.join('\n')};
}
function toMarkdown(text){
  var lines=splitLines(text);
  var out=['# 用户故事','| 编号 | 角色 | 目标 | 价值 | 用户故事 |','|------|------|------|------|----------|'];
  lines.forEach(function(line,i){
    var s=parseStory(line);
    var role=s.role||'用户', goal=s.goal||s.raw, value=s.value||'达成业务目标';
    var story='作为'+role+'，我希望'+goal+'，以便'+value+'。';
    out.push('| '+(i+1)+' | '+role+' | '+goal+' | '+value+' | '+story+' |');
  });
  return {markdown:out.join('\n'), count:lines.length};
}
var EXPORTS={splitLines:splitLines, parseStory:parseStory, genStory:genStory, toMarkdown:toMarkdown};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.UserStoryForgePure = EXPORTS; }
